        if (m_Updater) {
            m_Updater->stop(); // Stop updating thread
        }
    }

signals:
    void sgnl_ValueChanged();

private slots:
    void updateValue(const QPointF& value) {
        m_Value = value;
        emit sgnl_ValueChanged();
    }

private:
